      this.memberError(poolId, 'Choose a person or pool to add.');
      return;
    }
    const [kind, idText] = member.split(':');
    const id = Number(idText);
    if (!SHARE.test(shareText) || cents(shareText) <= 0 || cents(shareText) > 10000) {
